"""Manual source-image authoring; choice numbers follow independent calculations."""
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')}
items=[]
def add(q,stem,conditions,values,reasons,answer,solution,core,theory,knowledge,figure=False,citations=None):
 r=by[q]
 assert len(values)==len(reasons)==5
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,conditions=conditions,choices={str(i):dict(value=v,verdict='適切な解答候補' if str(i)==answer else '不適切な解答候補',reason=why) for i,(v,why) in enumerate(zip(values,reasons),1)},figures='流れ図の初期化、分岐、添字、更新と終了条件を画像確認。' if figure else '図なし。5肢の値または記述を画像確認。',ambiguity='',evidence=[f'extracted/pages/{r["source_year_directory"]}/basic/page_{p:03}.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],summary=stem,core_concept=core,required_knowledge=knowledge,solution=solution,independent_answer=answer,answer_reason=solution,learning_points={'radix':'位取りの基数と、小数の有限表現が可能かどうかを区別する。小数は2倍操作で上位桁から求める。','complement':'桁数を固定してから補数を計算する。1の補数はビット反転、2の補数はさらに1を加える。','floating':'先頭の1を除く仮数部と、バイアスを加えた指数部を別々に作る。符号を最後まで追跡する。','error':'表現・演算の丸め、相殺による桁落ち、大小の加算による情報落ち、範囲超過を区別する。','capacity':'単位あたりのバイト数を先に定義し、容量の数値だけを比べない。','horner':'各更新後の値が読了したビット列の値であるという不変条件を用い、最後の一致だけで途中を省略しない。'}[theory],theory_references=['theory:information:'+theory],discipline_id='basic_1',concept_id='concept_019',classification_reason='原典の問題幹・条件・5肢を確認。数値表現又は基数変換に伴う誤差を問うため情報・論理の数値表現へ分類する。',calculation='true',figure='true' if figure else 'false',law='false',evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='1',figure_reading='2' if figure else '0',difficulty='2',difficulty_reason='物理計算に比べ計算負荷は小さいが、有限ビットの規約と更新順を理解する必要がある。'),citations=citations or [],foundationality='high',transferability='high'))

add('H24-REG-BASIC-2-1','数値表現と誤差に関する5記述から、最も適切なものを選ぶ。',{'仮定':'選択肢5は10進7桁精度で100000.0と0.01を加算する。'},['浮動小数点では桁あふれ・桁不足はない','桁落ちは乗算又は除算で生じる','固定小数点なら誤差はない','単精度の丸め誤差は倍精度により改善できることが多い','10進7桁なら100000.0+0.01に誤差はない'],['指数の範囲は有限であり、上限・下限の範囲超過がある。','近い数の減算又は逆符号の加算で有効桁が相殺される現象である。','小数桁数が有限なら表現できない値があり、演算後の丸めもある。','通常は仮数の桁数が増え、同じ計算の表現・丸め誤差を小さくできる。ただし常に完全に解消するという主張ではない。','正確な100000.01には8桁の有効数字が必要で、7桁では0.01が保持されない。'],'4','有限精度は固定・浮動のどちらでも誤差を生じ得る。浮動小数点には有限の指数範囲もある。4の「改善できることが多い」は仮数精度を増す効果として適切である。5は大小の加算で小さい量が失われる例である。','有限精度計算で誤差を生む原因','error','有効桁数、丸め、桁落ち、情報落ち、指数範囲。',citations=['goldberg1991'])

add('H25-REG-BASIC-2-5','0.85を二進小数4桁で切り捨て、その値を半分にして再度4桁で切り捨てる。',{'初期値':'10進0.85','演算':'二進小数点以下5桁目以降を各段階で切捨て。初回の格納値を2で除する。','空欄順':'初回の二進表現／除算後の二進表現／除算後の十進値'},['0.1101／0.0101／0.375','0.1101／0.0110／0.375','0.1101／0.0110／0.425','0.1010／0.0101／0.375','0.1010／0.0101／0.425'],['除算後の0110を0101としている。0101の値も0.3125であり提示の0.375に合わない。','13/16を半分にし、6/16へ切り捨てる両段階と一致する。','0.425は元の0.85を正確に半分にした値であり、段階ごとの切捨てを無視している。','初回は1101であり1010ではない。除算後の0101も誤りである。','初回と除算後のビットが誤りで、0.425も切捨て後の値ではない。'],'2',r'初回は \(\lfloor16\times0.85\rfloor/16=13/16=(0.1101)_2\)。これを半分にすると13/32=(0.01101)₂である。4桁に切り捨てると6/16=(0.0110)₂=0.375になる。','有限二進小数の量子化と演算順','radix','二進小数の位取り、切捨てによる量子化。')

add('H27-REG-BASIC-2-1','二進計算機で0.01を100回加え、正しいプログラムでも結果が1と一致しない原因を選ぶ。',{'入力':'10進0.01','繰返し':'100回加算。プログラムの誤りはない。'},['桁落ち','情報落ち','オーバーフロー','アンダーフロー','丸め誤差'],['ほぼ等しい量を減算して有効桁が失われる状況ではない。','著しく桁の異なる量を加算して小さい量が消える原因を主題としていない。','1付近の合計が通常の浮動小数点の上限を超える状況ではない。','0.01は通常の浮動小数点の最小正数より十分大きい。','0.01は二進有限小数で表せず、入力表現と各加算の丸めが蓄積し得る。'],'5','0.01=1/100の既約分母には5が残り、二進有限小数にはならない。格納値は近似であり、加算の結果も有限桁へ丸められるので、100回の累積値が数学的な1と一致しないことがある。誤差の符号や実際の値は形式・演算順に依存する。','進数依存の表現誤差と累積','error','有限二進小数の条件、入力と演算の丸め。',citations=['goldberg1991'])

add('H27-REG-BASIC-2-3','10進0.1を二進小数で小数点以下16桁まで表す。',{'入力':'10進0.1','表示桁':'小数点以下16桁'},['0.0000011001100110','0.0000110011001100','0.0001100110011001','0.0011001100110011','0.0110011001100110'],['先頭の1が6桁目にあり、0.1の4桁目と合わない。','先頭の1が5桁目で、0.1の表現を一桁右へずらした形である。','反復2倍の出力0001100110011001に一致する。','先頭の1が3桁目で、0.1の表現を一桁左へずらした形である。','先頭の1が2桁目で、0.1より大きい値である。'],'3','小数を順に2倍し整数部を取り出す。0.1→0.2→0.4→0.8→1.6で最初の4桁は0001である。残り0.6から1.2、0.4、0.8、1.6と循環し、0011の反復が現れる。16桁は0001100110011001となる。','循環二進小数の生成','radix','小数の反復2倍法、分母と有限展開。')

for q,values,answer in [('H27-REG-BASIC-2-4',['1.8 TB','2.0 TB','2.1 TB','2.2 TB','2.3 TB'],'1'),('R01-RET-BASIC-2-3',['1.6 TB','1.8 TB','2.0 TB','2.2 TB','2.4 TB'],'2')]:
 add(q,'10進表記で2 TBの記憶容量を、問題が定義する2進表記のTBへ換算する。',{'容量':'2×10^12 B','単位':'設問は10進1 TB=10^12 B、2進1 TB=2^40 Bと定義する。現行の明確な名称では後者は1 TiBである。'},values,[('2×10^12/2^40≈1.819を小数1桁へ概算した値に一致する。' if str(i)==answer else v+'は2×10^12/2^40≈1.819の概算と合わない。単位当たりの容量が大きくなるので数値は2より小さくなる。') for i,v in enumerate(values,1)],answer,r'容量をバイトへ統一してから新単位で割る。\(2\times10^{12}/2^{40}=2(1000/1024)^4\simeq1.819\)であり、約1.8となる。原典の「2進のTB」を現在の用語で明確に区別すればTiBである。','情報容量の接頭語と単位換算','capacity','TBとTiBの単位量、情報量保存。',citations=['nist_binary_prefix'])

add('H28-REG-BASIC-2-3','11を例に、2で割った余りを配列へ格納する二進変換流れ図の分岐と更新を選ぶ。',{'初期化':'I=-1、Nは自然数。','操作':'Nと0を比較。継続側でIを1増やしてA[I]へNを2で割った余りを保存し、Nを更新。終了側でA[I]からA[0]を逆順表示。','空欄順':'アは継続条件、イは終了条件、ウはNの更新。'},['N>0／N=0／Nを2で割った商','N>0／N=0／Nを2で割った余り','N=0／N>0／Nを2で割った商','N=0／N>0／Nを2で割った余り','N>0／N=0／2N'],['正のNについて余りを保存し整数商へ更新、商0で終了する。','余りをNへ戻すと桁の取り出しが進まず、余り1では停止しない。','初期値11が正の段階で終了し、桁を生成できない。','分岐が逆であり、更新も桁を消去する商ではない。','Nを増加させるため正の入力で終了に近づかない。'],'1','Nを11→5→2→1→0と整数商で更新し、余りは1、1、0、1の順で得る。格納順は下位桁からなので逆順表示により1011となる。正のNで継続し、N=0で停止する。N=0を入力として許す実装ではゼロ表示の別処理が必要だが、例示の正の入力の空欄判定には影響しない。','整数商と余りによる基数変換','radix','除法の等式N=2q+r、0≤r<2、終端条件、配列の順序。',figure=True)

float_values=[['1／10000001／10010000000000000000000','1／10000010／10100000000000000000000','0／10000001／10100000000000000000000','0／10000010／10100000000000000000000','0／10000001／10100000000000000000000'],['1／10000010／10100000000000000000000','1／10000001／10100000000000000000000','0／10000001／10100000000000000000000','0／10000001／10100000000000000000000','0／10000010／10100000000000000000000']]
for q,values,answer in [('H29-REG-BASIC-2-2',float_values[0],'4'),('R01-RET-BASIC-2-4',float_values[1],'5')]:
 reasons=[]
 for v in values:
  s,e,f=v.split('／');bad=[]
  if s!='0':bad.append('13.0は正なので符号は0である')
  if e!='10000010':bad.append('指数3へ127を加えると130で、10000010になる')
  if f!='10100000000000000000000':bad.append('0.625=(0.101)₂なので仮数部は101の後に0が20個である')
  reasons.append('符号・指数・仮数の3欄がすべて一致する。' if not bad else '。'.join(bad)+'。')
 add(q,'13.0を、符号1ビット・指数8ビット・仮数23ビットの指定浮動小数点形式へ変換する。',{'数値':'13.0','表現':'正規化値±2^a(1+x)、0≤x<1。指数はa+127、仮数はxの二進小数23桁。','原典の導入範囲':'絶対値2^-126以上2^128未満。IEEE形式全体の表現可能範囲と完全には同一でないが、13.0には影響しない。','原典例':'-6.5=-2^2(1+0.625)、符号1、指数129。','空欄順':'符号／指数／仮数'},values,reasons,answer,r'\(13=8(1+0.625)=2^3(1+0.101_2)\)である。正なので符号0、指数欄は3+127=130=(10000010)₂。仮数欄は先頭の暗黙の1を保存せず、0.625の小数桁101に0を20個加えた23ビットとなる。','正規化と指数バイアス','floating','単精度の3欄、指数バイアス127、正規化先頭1の省略。',citations=['oracle_single'])

for q,bits,values,answer in [('H30-REG-BASIC-2-3','01011',['11011／10100','10101／11011','10101／10100','10100／10101','11011／11011'],'3'),('R02-REG-BASIC-2-4','100110',['000110／000101','011010／011001','000111／000110','011001／011010','011000／011001'],'2')]:
 k=len(bits);n=int(bits,2);two=format(2**k-n,f'0{k}b');one=format(2**k-1-n,f'0{k}b');reasons=[]
 for v in values:
  a,b=v.split('／');bad=[]
  if a!=two:bad.append('2の補数は'+two+'であり、'+a+'ではない')
  if b!=one:bad.append('1の補数は'+one+'であり、'+b+'ではない')
  reasons.append('2の補数と1の補数がともに一致する。' if not bad else '。'.join(bad)+'。')
 add(q,bits+'の'+str(k)+'桁を固定して、2の補数と1の補数を求める。',{'対象二進数':bits,'桁数':k,'定義':'2の補数は2^k-X、1の補数は(2^k-1)-X。','空欄順':'2の補数／1の補数'},values,reasons,answer,f'{bits}の十進値は{n}である。2の補数は{2**k}-{n}={2**k-n}、{two}となる。1の補数は{2**k-1}-{n}={2**k-1-n}、{one}となる。後者は各ビットを反転し、前者はそこへ1を加えても得られる。','桁数を固定した補数と負数表現','complement','基数の補数と基数から1を引いた補数、固定桁幅。')

for q,bits,values,answer,gaps in [('R02-REG-BASIC-2-5','11010101',['25／52／105','25／52／106','26／52／105','26／53／105','26／53／106'],'5','26／53／106'),('R04-REG-BASIC-2-5','11001011',['12／25／51／102','13／26／50／102','13／26／52／101','13／25／50／101','12／25／50／101'],'5','12／25／50／101')]:
 trace=[];s=0
 for b in bits:s=2*s+int(b);trace.append(s)
 reasons=[]
 for v in values:
  bad=[f'{"アイウエ"[i]}は{b}であり{a}ではない' for i,(a,b) in enumerate(zip(v.split('／'),gaps.split('／'))) if a!=b]
  reasons.append('全更新値が漸化式s←2s+aᵢに一致する。' if not bad else '。'.join(bad)+'。')
 add(q,bits+'を上位桁から二進→十進変換する流れ図の途中値を求める。',{'入力二進数':bits,'初期値':'s←最上位ビット、i←次のビット位置。','反復':'i≥0ならs←2s+a_i、i←i-1。i<0で終了。','空欄':'上位4桁までを処理した後から最終更新直前までの値。' if q.startswith('R02') else '上位3桁までを処理した後から最終更新直前までの値。'},values,reasons,answer,'上位から1ビット読むたび、既読の値を2倍して新しいビットを加える。更新列は'+'→'.join(map(str,trace))+'であり、空欄は'+gaps+'となる。最後だけでなく全段階の添字とビットを対応させる。','桁評価の漸化式とループ不変条件','horner','位置記数法、s←2s+a_i、上位からの評価、添字の下降。',figure=True)

add('R01-REG-BASIC-2-1','10進11.5を二進数と16進数へ変換する。',{'入力':'11.5','空欄順':'二進数／16進数'},['1011.1／B.8','1011.0／C.8','1011.1／B.5','1011.0／B.8','1011.1／C.5'],['11=8+2+1、0.5=1/2であり、16進では11=B、0.5=8/16になる。','整数12を表すCと、小数0を表す.0が誤りである。','16進.5は5/16であり、十進0.5とは異なる。','二進.0は小数0であり、0.5を失っている。','整数C=12、小数.5=5/16の両方が異なる。'],'1','11=2³+2+1より整数部1011、0.5=2⁻¹より小数部.1となる。16進整数11はBで、小数0.5を16倍すると8なのでB.8である。二進小数.1を.1000と4ビットにそろえて8へ変換してもよい。','二進と16進の位取り対応','radix','基数の位取り、4ビットと16進1桁の対応。')

add('R06-REG-BASIC-2-1','10進0.6を二進小数で小数点以下16桁まで表す。',{'入力':'10進0.6','表示桁':'小数点以下16桁'},['0.1001100110011001','0.1011001100110011','0.1100000000000000','0.1100110011001100','0.1110011001100110'],['0.6の反復2倍から得る1001100110011001に一致する。','最初の3桁を101としているが、0.6では100となる。','0.75の有限二進表現であり、0.6と異なる。','先頭2桁が11なら0.75以上となり、0.6と合わない。','先頭3桁が111なら0.875以上となり、0.6と合わない。'],'1','0.6を2倍して整数1、残り0.2から0、残り0.4から0、残り0.8から1、残り0.6へ戻る。したがって1001を反復し、小数16桁は1001100110011001となる。分母5は2の累乗ではないので展開は有限ではない。','循環二進小数と表示精度','radix','反復2倍法、剰余の循環。')

for e in items:
 e['discipline_id']='basic_2_2'
assert len(items)==15
(ROOT/'config/authored_batches/S7_003_numerical_representation.json').write_text(json.dumps(dict(batch_id='S7_003_numerical_representation',reference_date='2026-10-08',scope='15問の全条件・5肢・3流れ図を画像確認。基数・補数・浮動小数点・誤差・容量の概念バッチ。',questions=items),ensure_ascii=False,indent=2)+'\n')
print('Prepared',len(items),'manual records without accessing official answer values')
